import Foundation
import Metal
import os

/// Growing Neural CA, Mordvintsev et al. (2020), ex3_planarian weights.
/// Straightforward GPU scalar arithmetic, not Metal tensor acceleration.
/// Adapted from public/ca.js (Apache 2.0) and the repository model (CC BY 4.0);
/// attribution and both license texts are in NOTICE.txt and third_party/growing-ca.
public final class NeuralCAData: LerpDataProvider {
    static let weights = [
        "",
        ""
    ]
    static let source: String = {
        let constants = weights.enumerated().map { i, encoded in
            "constant uchar w\(i)[] = {" + Data(base64Encoded: encoded)!.map(String.init).joined(separator: ",") + "};\n"
        }.joined()
        return constants + """
float4 state(texture2d<float, access::read> s0, texture2d<float, access::read> s1, texture2d<float, access::read> s2, texture2d<float, access::read> s3, int2 p, constant LerpSimFrame& f, int band) {
 p = (p + int2(f.size)) % int2(f.size);
 if (f.config[0].x > 0.5 && f.step == 320 && length(float2(p)-float2(f.size)*0.5-float2(8,0)) < 12.0) return 0;
 switch(band) { case 0:return s0.read(uint2(p)); case 1:return s1.read(uint2(p)); case 2:return s2.read(uint2(p)); default:return s3.read(uint2(p)); }
}
kernel void ncaSeed(constant LerpSimFrame& f [[buffer(0)]], texture2d<float, access::write> o0 [[texture(8)]], texture2d<float, access::write> o1 [[texture(9)]], texture2d<float, access::write> o2 [[texture(10)]], texture2d<float, access::write> o3 [[texture(11)]], uint2 p [[thread_position_in_grid]]) {
 if(any(p>=f.size)) return; bool center=all(p==f.size/2); o0.write(center?float4(0,0,0,1):float4(0),p); o1.write(float4(center),p); o2.write(float4(center),p); o3.write(float4(center),p);
}
kernel void ncaDelta(constant LerpSimFrame& f [[buffer(0)]], texture2d<float, access::read> s0 [[texture(0)]], texture2d<float, access::read> s1 [[texture(1)]], texture2d<float, access::read> s2 [[texture(2)]], texture2d<float, access::read> s3 [[texture(3)]], texture2d<float, access::write> o4 [[texture(12)]], texture2d<float, access::write> o5 [[texture(13)]], texture2d<float, access::write> o6 [[texture(14)]], texture2d<float, access::write> o7 [[texture(15)]], uint2 p [[thread_position_in_grid]]) {
 if(any(p>=f.size)) return;
 float x[48];
 for(int b=0;b<4;b++) { float4 v=state(s0,s1,s2,s3,int2(p),f,b), dx=0,dy=0;
 for(int y=-1;y<=1;y++) for(int xx=-1;xx<=1;xx++) { float4 a=state(s0,s1,s2,s3,int2(p)+int2(xx,y),f,b); dx+=a*float(xx*(y==0?2:1))/8.0; dy+=a*float(y*(xx==0?2:1))/8.0; }
 for(int c=0;c<4;c++) { x[b*4+c]=v[c]; x[16+b*4+c]=dx[c]; x[32+b*4+c]=dy[c]; } }
 float h[128]; for(int o=0;o<128;o++) { float v=(float(w0[48*128+o])/255.0-0.5)*0.508971095085144; for(int i=0;i<48;i++) v+=x[i]*(float(w0[i*128+o])/255.0-0.5)*1.735606074333191; h[o]=max(v,0.0); }
 float4 r[4]; for(int o=0;o<16;o++) { float v=(float(w1[128*16+o])/255.0-0.5)*0.1896675080060959; for(int i=0;i<128;i++) v+=h[i]*(float(w1[i*16+o])/255.0-0.5)*0.8933451771736145; r[o/4][o%4]=v; }
 if(lerpSimHash(p.x,p.y,f.seed ^ f.epoch ^ f.step)>=0.5) for(int i=0;i<4;i++) r[i]=0;
 o4.write(r[0],p); o5.write(r[1],p); o6.write(r[2],p); o7.write(r[3],p);
}
kernel void ncaUpdate(constant LerpSimFrame& f [[buffer(0)]], texture2d<float, access::read> s0 [[texture(0)]], texture2d<float, access::read> s1 [[texture(1)]], texture2d<float, access::read> s2 [[texture(2)]], texture2d<float, access::read> s3 [[texture(3)]], texture2d<float, access::read> d0 [[texture(4)]], texture2d<float, access::read> d1 [[texture(5)]], texture2d<float, access::read> d2 [[texture(6)]], texture2d<float, access::read> d3 [[texture(7)]], texture2d<float, access::write> o0 [[texture(8)]], texture2d<float, access::write> o1 [[texture(9)]], texture2d<float, access::write> o2 [[texture(10)]], texture2d<float, access::write> o3 [[texture(11)]], uint2 p [[thread_position_in_grid]]) {
 if(any(p>=f.size)) return;
 // A single bounded, deterministic injury per epoch. Clear all channels at
 // generation 320; subsequent ordinary updates perform the healing.
 int2 wound = int2(p) - (int2(f.size) / 2 + int2(8, 0));
 if(f.config[0].x > 0.5 && f.step == 320 && wound.x * wound.x + wound.y * wound.y < 100) {
   o0.write(float4(0),p); o1.write(float4(0),p); o2.write(float4(0),p); o3.write(float4(0),p); return;
 }
 float pre=0,post=0;
 for(int y=-1;y<=1;y++) for(int x=-1;x<=1;x++) {int2 q=(int2(p)+int2(x,y)+int2(f.size))%int2(f.size); float a=state(s0,s1,s2,s3,q,f,0).a; pre=max(pre,a); post=max(post,a+d0.read(uint2(q)).a);}
 bool alive=min(pre,post)>=0.1; o0.write(alive?state(s0,s1,s2,s3,int2(p),f,0)+d0.read(p):float4(0),p); o1.write(alive?state(s0,s1,s2,s3,int2(p),f,1)+d1.read(p):float4(0),p); o2.write(alive?state(s0,s1,s2,s3,int2(p),f,2)+d2.read(p):float4(0),p); o3.write(alive?state(s0,s1,s2,s3,int2(p),f,3)+d3.read(p):float4(0),p);
}

"""
    }()
    let simulation: LerpGPUSimulation?
    let placeholder: MTLTexture?
    private var texture: MTLTexture?
    private var ready: UInt32 = 0
    public init(device: MTLDevice) {
        do {
            simulation = try LerpGPUSimulation(device: device, label: "neural-ca", source: Self.source,
                planes: (0..<8).map { .init("nca\($0)", pixelFormat: .rgba32Float) },
                seed: [.init("ncaSeed", writes: [0,1,2,3])],
                step: [.init("ncaDelta", writes: [4,5,6,7]), .init("ncaUpdate", writes: [0,1,2,3])])
        } catch {
            Logger(subsystem: LerpDefaults.productionModule, category: "neural-ca").error("kernel compilation failed: \(String(describing: error), privacy: .public)")
            simulation = nil
        }
        let d = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .rgba32Float, width: 1, height: 1, mipmapped: false)
        d.usage = .shaderRead
        placeholder = device.makeTexture(descriptor: d)
    }
    public var metalPrelude: String { "struct LerpNeuralCAFrame { uint ready; };" }
    public func bind(to encoder: MTLRenderCommandEncoder, uniforms: LerpUniforms) {
        encoder.setFragmentBytes(&ready, length: MemoryLayout<UInt32>.size, index: 1)
        encoder.setFragmentTexture(texture ?? placeholder, index: 1)
    }
    public func encodeCompute(into commandBuffer: MTLCommandBuffer, uniforms: LerpUniforms, params: LerpParameterValues?) {
        let t = max(0, uniforms.time) * 12
        let epoch = Int(t / 640)
        let step = Int(t.truncatingRemainder(dividingBy: 640))
        let key = LerpGPUSimulation.Key(seed: uniforms.seed, epoch: epoch, width: 96, height: 96, config: [1])
        texture = simulation?.advance(commandBuffer, to: step, of: key)?.first
        ready = texture == nil ? 0 : 1
    }
}
